/* Force Multiplier 22.14.0 — shared instructional layer. No remote services.
   Sources: supplied 100 Skills draft, FLUX workshop, existing task map and training models.
   Explanatory examples are illustrative; they are not instructions for actual aircraft maintenance. */
(function(){'use strict';
const DATA=window.FMFundamentalsData||{};
const labels=['Show Me','Help Me','Let Me Try','Challenge Me','Prove I Can Do It'];
const E=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const seqs={
 checkerboard:{bad:['PFR','PFR','CURE','PBG','PBG','CURE','READY'],good:['PFR','PFR','PBG','PBG','CURE','READY','READY'],edge:['PFR','PFR','CURE','PBG','PBG','CURE','READY']},
 daily:{bad:['FLY','FLY','FLY','NMC','FLY','FLY','—'],good:['FLY','SPARE','FLY','FLY','TURN','FLY','—'],edge:['FLY','SPARE','NMC','HOLD','FLY','FLY','—']},
 phase:{bad:['FLY','FLY','PHASE','PHASE','HOLD','HOLD','—'],good:['FLY','HOLD','PHASE','FLY','FLY','SPARE','—'],edge:['FLY','HOLD','PHASE','HOLD','SPARE','HOLD','—']},
 planned:{bad:['PFR','PFR','HOLD','PBG','CURE','HOLD','—'],good:['PARTS','PFR','PFR','PBG','PBG','CURE','—'],edge:['PARTS','HOLD','PFR','PFR','PBG','CURE','—']},
 capacity:{bad:['PHASE','PHASE','HOLD','HOLD','FLY','FLY','—'],good:['PHASE','HOLD','FLY','SPARE','FLY','FLY','—'],edge:['PHASE','HOLD','NMC','SPARE','FLY','FLY','—']},
 recover:{bad:['FLY','NMC','HOLD','HOLD','HOLD','HOLD','—'],good:['FLY','NMC','SPARE','FLY','FLY','FLY','—'],edge:['FLY','NMC','HOLD','SPARE','FLY','FLY','—']},
 control:{bad:['FLY','FLY','HOLD','FLY','FLY','FLY','—'],good:['FLY','SPARE','HOLD','FLY','FLY','BRIEF','—'],edge:['FLY','SPARE','HOLD','HOLD','BRIEF','FLY','—']}
};
const glossary={FLY:'Planned fly',SPARE:'Protected spare',PHASE:'Phase inspection',HOLD:'Unavailable / hold',NMC:'Not mission capable',PFR:'Paint from red',PBG:'Paint back green',CURE:'Required cure',PARTS:'Prerequisite parts',BRIEF:'Leadership review',READY:'Available', '—':'No scheduled task'};
function findTask(area,m){const t=window.FMTaskMapData?.tasks||[];return t.find(x=>x.moduleArea===area&&x.moduleId===m.id)||null;}
function caseInfo(area,m,selection){const t=findTask(area,m),wrong=m.answers?.find((_,i)=>i!==m.answer)||'Proceed without source verification';
 const all=[
  {k:'bad',label:'Spot the problem',title:'What a flawed approach looks like',desc:t?.pitfall||`A tempting but unsupported shortcut: ${wrong}.`,focus:'Identify the error before deciding what to change.'},
  {k:'good',label:'Improve the work',title:'What a defensible approach looks like',desc:m.answerWhy||m.outcome,focus:'Compare the inputs, the sequence and the evidence.'},
  {k:'edge',label:'Know the boundary',title:'When you must stop or reconsider',desc:`A prerequisite, authorized limit, source document or resource may prevent the preferred option. ${m.why}`,focus:'Identify what you must verify or elevate rather than inventing permission.'}
 ];return all.find(x=>x.k===selection)||all[1];}
function boardMarkup(m,which){const rows=['A01','A02','A03'];let pattern=(seqs[m.id]||seqs.checkerboard)[which];let a01=['FLY','SPARE','FLY','FLY','FLY','—','—'],a03=['HOLD','SPARE','FLY','HOLD','FLY','—','—'];if(m.id==='phase'){a03=['HOLD','HOLD',which==='bad'?'PHASE':'FLY','FLY','SPARE','—','—']}if(m.id==='daily')a03=['FLY','FLY','SPARE','NMC','SPARE','—','—'];const matrix=[a01,pattern,a03];return `<div class="teach-board-scroll"><div class="teach-board" role="table" aria-label="Illustrative seven-day aircraft checkerboard"><div class="teach-board-line"><span class="teach-ac-label">Aircraft</span>${['Mon','Tue','Wed','Thu','Fri','Sat','Sun'].map(x=>`<span class="teach-day-label">${x}</span>`).join('')}</div>${rows.map((name,i)=>`<div class="teach-board-line"><strong class="teach-ac-label">${name}</strong>${matrix[i].map((tag,j)=>`<span class="teach-cell ${j>4?'weekend ':''}${tag.replace(/[^A-Z]/g,'').toLowerCase()}" title="${E(glossary[tag]||tag)}">${E(tag)}</span>`).join('')}</div>`).join('')}</div></div>`;}
function metricMarkup(m,which){const isRate=m.id==='rates', nums=[2,4,3,5],dens=[10,12,8,14],sorties=[42,48,45,55];if(isRate)return `<div class="teach-math"><div><small>Eligible fixes (within 8 hours)</small><b>${which==='edge'?'?':2}</b></div><span>÷</span><div><small>${which==='bad'?'Sorties (wrong denominator)':'Qualifying breaks'}</small><b>${which==='bad'?42:10}</b></div><span>× 100</span><strong>${which==='bad'?'4.8% ❌':which==='edge'?'HOLD':'20%'}</strong></div><p class="teach-note">Scenario assumption: 2 qualifying fixes of 10 qualifying breaks → 20%. Verify the current authorized metric definition and exclusions.</p>`;
return `<div class="teach-metric-bars">${nums.map((v,i)=>`<div><span>Week ${i+1}</span><span class="teach-metric-track"><i style="width:${(v/dens[i])*100}%" class="${which==='bad'?'mistake':''}"></i></span><b>${which==='edge'&&i===3?'source?':which==='bad'?Math.round(v/sorties[i]*100)+'%':Math.round(v/dens[i]*100)+'%'}</b></div>`).join('')}</div><p class="teach-note">${which==='bad'?'The chart uses unlike populations; comparison may be misleading.':which==='good'?'Each period uses a consistent, documented population and denominator.':'Before interpreting a change, verify missing periods, definitions and operational context.'}</p>`;}
function flowMarkup(area,m,which){let boxes=[];
 if(area==='documentation')boxes=which==='bad'?['Requirement','Wrong asset','Work claimed complete','No evidence']:which==='good'?['Current requirement','Applicability','JML / forecast','Scheduled work','Verified completion']:['Requirement','Missing approval','Hold / escalate','Preserve open item'];
 if(area==='integrity')boxes=which==='bad'?['Mismatch','Assume source','Overwrite value','Lost history']:which==='good'?['Approved source','Compare','Confirm authority','Scoped correction','Audit downstream']:['Conflicting sources','Hold discrepancy','Find authority','Follow up'];
 if(area==='dbm')boxes=which==='bad'?['User report','Grant admin','Still fails','No validation']:which==='good'?['Reproduce issue','Find failing layer','Authorize fix','Apply minimal change','Verify original task']:['Access looks correct','Interface failed','Escalate with evidence','Retest'];
 return `<div class="teach-flow">${boxes.map((v,i)=>`<div class="teach-flow-node ${which==='bad'?'bad':which==='edge'?'edge':'good'}"><small>${i+1}</small><b>${E(v)}</b></div>`).join('<span class="teach-flow-arrow" aria-hidden="true">→</span>')}</div>`;}
function compareMarkup(area,m,which){return window.FMVisuals?.lesson(area,m.id,which)||'';}
function gallery(area,m,which='good',compact=false){const x=caseInfo(area,m,which);return `<section class="teach-gallery ${compact?'compact':''}" aria-label="Visual concept gallery"><div class="teach-gallery-top"><div><strong>SEE THE CONCEPT</strong><p>Three views of the same fundamental · illustrative training data</p></div><span class="teach-case-tag">${E(x.label)}</span></div><div class="teach-case-tabs" role="group" aria-label="Choose a visual example">${[['bad','Wrong'],['good','Right'],['edge','Constraint']].map(([id,label])=>`<button type="button" data-teach-case="${id}" class="${id===which?'active':''}" aria-pressed="${id===which}">${label}</button>`).join('')}</div><div class="teach-case-inside"><div class="teach-case-caption"><strong>${E(x.title)}</strong><p>${E(x.desc)}</p></div>${compareMarkup(area,m,which)}<p class="teach-takeaway"><b>Notice:</b> ${E(x.focus)}</p></div><p class="teach-disclaimer">Visuals demonstrate decisions; real maintenance work must follow current applicable technical data, approvals and local requirements.</p></section>`;}
/* Use the exact task and its evidence in the task-map dialog. Do not show the
   nearest lesson's chart when the actual task concerns a different artifact. */
function taskGallery(t,m,which='bad'){
 const mode=['bad','good','edge'].includes(which)?which:'bad';
 const cases={
  bad:{label:'Spot the problem',title:'What a flawed approach looks like',desc:t.pitfall,focus:'Find the unsupported assumption, missing evidence or unverified status.'},
  good:{label:'Improve the work',title:'What good performance looks like',desc:t.proof,focus:'Compare the actual work and source evidence with the expected result.'},
  edge:{label:'Know the boundary',title:'What changes the decision',desc:t.scenario,focus:'Check applicability, authority, capacity and unresolved evidence before proceeding.'}
 };
 const x=cases[mode],art=window.FMVisuals?.task(t,mode)||'';
 return `<section class="teach-gallery task-specific" aria-label="${E(t.title)} visual concept gallery"><div class="teach-gallery-top"><div><strong>SEE THE ACTUAL TASK</strong><p>${E(t.title)} · three task-specific examples</p></div><span class="teach-case-tag">${E(x.label)}</span></div><div class="teach-case-tabs" role="group" aria-label="Choose a task example">${[['bad','Wrong'],['good','Right'],['edge','Constraint']].map(([id,label])=>`<button type="button" data-task-teachcase="${id}" class="${id===mode?'active':''}" aria-pressed="${id===mode}">${label}</button>`).join('')}</div><div class="teach-case-inside"><div class="teach-case-caption"><strong>${E(x.title)}</strong><p>${E(x.desc)}</p></div>${art}<p class="teach-takeaway"><b>Notice:</b> ${E(x.focus)}</p></div><p class="teach-disclaimer">Fictional instructional data. Validate real procedures and requirements through authorized unit processes.</p></section>`;
}
function contextOf(state){const area=state.module,mods=DATA;let key,m;
 if(area==='academy'){const n=state.academy?.mission||1;const map={1:['scheduling','daily'],2:['scheduling','recover'],3:['scheduling','phase'],4:['documentation','jml'],5:['analysis','rates'],6:['integrity','reconcile'],7:['dbm','troubleshoot']};[key,m]=map[n]||map[1];}
 else if(area==='flashcards'){key='analysis';m='rates';}
 else{key=area==='doc'?'documentation':area;
 const s=state.screen||'';const n=parseInt((s.match(/\d+/)||[])[0]||'0',10);
 if(key==='scheduling')m=n>=8?'control':n>=7?'checkerboard':n>=5?'capacity':n>=3?'phase':'daily';
 else if(key==='analysis')m=s==='metric'?'rates':s==='sim4'?'drivers':s==='sim3test'||s==='sim5'?'stats':s==='sim6'?'brief':s==='sim2'?'trends':'question';
 else if(key==='documentation')m=s==='phase'||s==='inspection'?'forecast':'jml';
 else if(key==='integrity')m=n>=9?'prevent':n>=7?'correct':n>=4?'reconcile':'authority';
 else if(key==='dbm')m=n>=6?'continuity':n>=5?'change':n>=4?'interface':n>=3?'troubleshoot':'access';
 }
 const mod=mods[key]?.modules?.find(x=>x.id===m)||mods[key]?.modules?.[0];return mod?{area:key,mod,id:`${area}:${state.screen||'home'}`} : null;}
function ensure(state){let c=state.teaching||(state.teaching={});if(!Number.isInteger(c.stage)||c.stage<0||c.stage>4)c.stage=0;if(!c.case)c.case='good';if(!Array.isArray(c.records))c.records=[];if(!c.notes)c.notes={};return c;}
function activeIndependent(state){const c=ensure(state);return (c.stage===3||c.stage===4)&&!!c.open&&state.module!=='fundamentals';}
function renderCoach(state){const z=contextOf(state);if(!z)return '';const c=ensure(state),d=z.mod,rec=c.records.filter(r=>r.task===z.id).length;
 let body='';
 if(c.stage===0)body=`<p>${E(d.outcome)}</p>${gallery(z.area,d,c.case,true)}`;
 if(c.stage===1)body=`<p>${E(d.why)}</p><ol>${d.steps.map(s=>`<li>${E(s)}</li>`).join('')}</ol><p class="teach-note">Help is permitted in this mode. Assistance will not count as independent evidence.</p>`;
 if(c.stage===2)body=`<p>Try the live exercise below without a model answer. If needed, open Help Me and review the decision steps.</p><div class="teach-try">${E(d.scenario)}</div>`;
 if(c.stage===3)body=`<p><b>Challenge mode:</b> Work the live scenario below. Model answers and hints are temporarily locked while this panel is open. Use the exercise's New Variation control if it is available.</p><div class="teach-risk">Critical errors—such as using unavailable aircraft, inventing evidence, or granting unauthorized access—must be corrected before advancing.</div>`;
 if(c.stage===4)body=`<p><b>Independent work record.</b> Complete the live task, then describe the outcome, evidence and remaining risks. This is a trainee-submitted record for instructor review, not an automated qualification.</p><div class="teach-proof-form"><label>Decision / result<textarea data-coach-note="decision" rows="2" placeholder="What did you do and what was the result?">${E(c.notes[z.id]?.decision||'')}</textarea></label><label>Sources / evidence<textarea data-coach-note="evidence" rows="2" placeholder="What source facts or requirements support the answer?">${E(c.notes[z.id]?.evidence||'')}</textarea></label><label>Limitations / risk<textarea data-coach-note="risk" rows="2" placeholder="What changed, what remains unknown, and what must be escalated?">${E(c.notes[z.id]?.risk||'')}</textarea></label><button data-coach-save="1" class="teach-save">Save attempt for instructor review</button><span>${rec} saved attempt(s) on this device</span></div>`;
 return `<section class="teach-coach ${c.open?'open':''}" aria-label="Training coach"><div class="teach-coach-head"><div><span class="teach-coach-kicker">TRAIN WHILE YOU WORK · ${E(labels[c.stage].toUpperCase())}</span><strong>${E(d.title)}</strong></div><button data-coach-toggle="1" aria-expanded="${!!c.open}">${c.open?'Hide coaching ▴':'Teach this skill ▾'}</button></div>${c.open?`<div class="teach-coach-controls" role="group" aria-label="Learning stage">${labels.map((x,i)=>`<button data-coach-stage="${i}" class="${i===c.stage?'active':''}" aria-pressed="${i===c.stage}">${i+1}. ${E(x)}</button>`).join('')}</div><div class="teach-coach-body">${body}${c.notice?`<p class="teach-coach-notice" role="status">${E(c.notice)}</p>`:''}<button class="teach-lesson-link" data-coach-lesson="1">Open the full fundamentals lesson ↗</button></div>`:''}</section>`;
}
function handleClick(dataset,state,ui){const c=ensure(state),z=contextOf(state);
 if(dataset.coachToggle!==undefined){c.open=!c.open;c.notice='';ui.save();ui.render();return true}
 if(dataset.coachStage!==undefined){c.stage=Math.min(4,Math.max(0,Number(dataset.coachStage)));c.open=true;c.notice='';ui.save();ui.render();return true}
 if(dataset.coachLesson!==undefined&&z){const f=state.fundamentals||(state.fundamentals={});f.area=z.area;f.lesson=z.mod.id;f.screen='lesson';f.step=0;ui.save();ui.setRoute('fundamentals','home');return true}
 if(dataset.teachCase!==undefined&&state.module!=='fundamentals'&&z){c.case=dataset.teachCase;ui.save();ui.render();return true}
 if(dataset.coachSave!==undefined&&z){const n=c.notes[z.id]||{};if(!['decision','evidence','risk'].every(k=>(n[k]||'').trim().length>=15)){c.notice='Complete all three fields with at least 15 characters each before saving the attempt.';ui.save();ui.render();return true;}c.records.push({task:z.id,lesson:z.mod.title,at:new Date().toISOString(),mode:'awaiting instructor review',decision:n.decision,evidence:n.evidence,risk:n.risk});c.records=c.records.slice(-250);c.notice='Attempt saved locally for instructor review. This does not confer proficiency or official qualification.';ui.save();ui.render();return true}
 if(activeIndependent(state)&&(dataset.academyAction==='model'||dataset.academyAction==='hint'||dataset.slideAction==='hint'||dataset.action==='show-me'||dataset.action==='doc-model'||dataset.action==='doc-inspect-model'||dataset.action==='doc-phase-model'||dataset.action==='reveal-metric'||dataset.action==='reveal-fhp')){c.notice='Model answer and hints are unavailable in Challenge / Prove mode. Switch to Help Me to receive coaching.';ui.save();ui.render();return true}
 return false;}
function handleInput(target,state,ui){if(!target.dataset?.coachNote)return false;const z=contextOf(state);if(!z)return false;const c=ensure(state);const n=c.notes[z.id]||(c.notes[z.id]={});n[target.dataset.coachNote]=target.value.slice(0,8000);ui.save();return true}
window.FMTeaching={labels,gallery,taskGallery,caseInfo,renderCoach,handleClick,handleInput,ensure,contextOf,activeIndependent};
})();
